import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import type { VariantProps } from "class-variance-authority";
import { cn } from "@/ui/utils";
import { LoaderCircle, type LucideIcon } from "lucide-react";
import { buttonVariants } from "./button-variants";

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>, VariantProps<typeof buttonVariants> {
  asChild?: boolean;
  /** Prefer icon + text for actions. Keep labels stable while loading. */
  icon?: LucideIcon;
  loading?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      className,
      variant,
      size,
      asChild = false,
      icon: Icon,
      loading = false,
      disabled,
      children,
      ...props
    },
    ref,
  ) => {
    const Comp = asChild ? Slot : "button";
    // Slot must receive the caller's single child, without a wrapper.
    const content = asChild ? (
      children
    ) : (
      <>
        {Icon &&
          (loading ? (
            <LoaderCircle aria-hidden="true" className="animate-spin motion-reduce:animate-none" />
          ) : (
            <Icon aria-hidden="true" />
          ))}
        {!Icon && loading ? (
          <>
            <span className="inline-flex items-center justify-center gap-2 opacity-0">
              {children}
            </span>
            <LoaderCircle
              aria-hidden="true"
              className="absolute animate-spin motion-reduce:animate-none"
            />
          </>
        ) : (
          children
        )}
      </>
    );
    return (
      <Comp
        className={cn(
          buttonVariants({ variant, size, className }),
          loading && "disabled:!opacity-100",
        )}
        ref={ref}
        {...props}
        disabled={disabled || loading}
        aria-busy={loading || undefined}
        aria-disabled={disabled || loading || undefined}
        tabIndex={asChild && (disabled || loading) ? -1 : props.tabIndex}
        onClickCapture={(event) => {
          if (disabled || loading) {
            event.preventDefault();
            event.stopPropagation();
            return;
          }
          props.onClickCapture?.(event);
        }}
      >
        {content}
      </Comp>
    );
  },
);
Button.displayName = "Button";

/** Compact toolbar action with a required accessible name and native tooltip. */
const IconButton = React.forwardRef<
  HTMLButtonElement,
  Omit<ButtonProps, "children" | "asChild" | "size" | "icon"> & {
    icon: LucideIcon;
    label: string;
    size?: "icon" | "icon-sm";
  }
>(({ label, size = "icon-sm", variant = "ghost", ...props }, ref) => (
  <Button {...props} ref={ref} size={size} variant={variant} aria-label={label} title={label} />
));
IconButton.displayName = "IconButton";

export { Button, IconButton };

import { cva } from "class-variance-authority";

/**
 * The button's shapes. Kept beside `button.tsx` rather than inside it, so a test can
 * read the classes without rendering, and so the .tsx exports only components.
 */
export const buttonVariants = cva(
  "relative inline-flex shrink-0 items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-[color,background-color,box-shadow,opacity] duration-150 ease-out focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-40 aria-disabled:pointer-events-none aria-disabled:opacity-40 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/90",
        secondary:
          "bg-secondary text-secondary-foreground shadow-[var(--shadow-border)] hover:shadow-[var(--shadow-border-hover)]",
        outline: "bg-transparent text-foreground shadow-[var(--shadow-border)] hover:bg-secondary",
        ghost: "text-muted-foreground hover:bg-secondary hover:text-foreground",
        destructive: "bg-destructive text-white hover:bg-destructive/90",
        link: "text-foreground underline-offset-4 hover:underline",
      },
      size: {
        default: "h-9 px-3",
        sm: "h-8 px-2.5 text-xs",
        lg: "h-10 px-4",
        icon: "size-9 p-0",
        "icon-sm": "size-8 p-0",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
);

import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { Save, RefreshCw } from "lucide-react";
import { expect, it } from "vitest";
import { Button, IconButton } from "./button";
import { buttonVariants } from "./button-variants";

it("uses consistent compact geometry across visual variants", () => {
  for (const variant of ["default", "secondary", "outline", "ghost", "destructive"] as const) {
    const classes = buttonVariants({ variant });
    expect(classes).toContain("h-9");
    expect(classes).toContain("rounded-md");
    expect(classes).toContain("gap-2");
    expect(classes).not.toContain("scale-");
  }
});
it("renders decorative icons with the unchanged label and disables while loading", () => {
  const html = renderToStaticMarkup(
    createElement(Button, { icon: Save, loading: true }, "Save record"),
  );
  expect(html).toContain('disabled=""');
  expect(html).toContain('aria-busy="true"');
  expect(html).toContain('aria-hidden="true"');
  expect(html).toContain("animate-spin");
  expect(html).toContain("Save record");
  expect(html).not.toContain("Saving");
  expect((html.match(/<svg/g) ?? []).length).toBe(1);
});
it("keeps text-only labels in layout and the accessibility tree while busy", () => {
  const html = renderToStaticMarkup(createElement(Button, { loading: true }, "Continue"));
  expect(html).toContain("opacity-0");
  expect(html).toContain("Continue");
  expect(html).not.toContain("invisible");
});
it("provides an accessible label and tooltip on icon-only buttons", () => {
  const html = renderToStaticMarkup(
    createElement(IconButton, { icon: RefreshCw, label: "Refresh connections" }),
  );
  expect(html).toContain('aria-label="Refresh connections"');
  expect(html).toContain('title="Refresh connections"');
  expect(html).toContain("size-8");
});
it("preserves slotted links and removes disabled ones from tab order", () => {
  const html = renderToStaticMarkup(
    createElement(
      Button,
      { asChild: true, disabled: true },
      createElement("a", { href: "/assets" }, "Assets"),
    ),
  );
  expect(html).toContain('<a href="/assets"');
  expect(html).toContain('aria-disabled="true"');
  expect(html).toContain('tabindex="-1"');
  expect(html).not.toContain("<button");
});
